    // State machine states
    typedef enum {IDLE, SHIFT, COUNT, DONE} state_t;
    state_t state, next_state;

    // State machine logic
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    // Next state logic
    always @ (*) begin
        case (state)
            IDLE: begin
                if (data) begin
                    next_state = SHIFT;
                end else begin
                    next_state = IDLE;
                end
            end
            SHIFT: begin
                if (ack) begin
                    next_state = COUNT;
                end else begin
                    next_state = SHIFT;
                end
            end
            COUNT: begin
                if (done_counting) begin
                    next_state = DONE;
                end else begin
                    next_state = COUNT;
                end
            end
            DONE: begin
                next_state = IDLE;
            end
        endcase
    end

    // Output logic
    always @ (*) begin
        case (state)
            IDLE: begin
                shift_ena = 1'b0;
                counting = 1'b0;
                done = 1'b0;
            end
            SHIFT: begin
                shift_ena = 1'b1;
                counting = 1'b0;
                done = 1'b0;
            end
            COUNT: begin
